  async *streamGenerate(){},getModelCapabilities(){return {supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:32000,maxInputTokens:32000,maxOutputTokens:512};},validateConfig:async()=>true,listModels:async()=>[]};
