 agent.context.registerPlugin(new Data());agent.context.registerContextContributor('retrieval',{getRevision:()=>1,contribute:async({signal})=>{calls.collect++;await new Promise((resolve,reject)=>{const timer=setTimeout(resolve,delay);signal.addEventListener('abort',()=>{clearTimeout(timer);reject(signal.reason);},{once:true});});return [{id:'row',text:'CURRENT_VALUE'}];}});
